import json

with open('json/drivers.json', 'r') as f:
    data = json.load(f)

for record in data['records']:
    if record.get('surname') == 'Yoong' and record.get('forename') == 'Alex':
        print(f"Found Alex Yoong: driverId={record['driverId']}, driverRef={record['driverRef']}")
